public class DigitExtractorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("extractDigits(\"a1b22c\")", "122", DigitExtractor.extractDigits("a1b22c"));
        check("no digits at all", "", DigitExtractor.extractDigits("no digits!"));
        check("leading zeros are kept", "007", DigitExtractor.extractDigits("agent 007!"));
        check("digits with punctuation", "314", DigitExtractor.extractDigits("3.14 is pi"));
        check("phone number", "5551234", DigitExtractor.extractDigits("(555) 123-4"));
        check("all digits already", "98765", DigitExtractor.extractDigits("98765"));
        check("empty input", "", DigitExtractor.extractDigits(""));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

